function tapStage(x, y) {
  if (!cur || drag) return;
  if (x > stageRect.left && x < stageRect.left + stageRect.w && y > stageRect.top && y < stageRect.top + stageRect.h) { sfxCoo(cur.id); bounce(cur, 'jump'); cur.happyT = 0.9; hearts(2); }
}
