function layout() {
  W = window.innerWidth; H = window.innerHeight; DPR = Math.min(window.devicePixelRatio || 1, 1.5);
  bgCv.width = W; bgCv.height = H; bgCv.style.width = W + 'px'; bgCv.style.height = H + 'px';
  fxCv.width = Math.round(W * DPR); fxCv.height = Math.round(H * DPR); fxCv.style.width = W + 'px'; fxCv.style.height = H + 'px';
  if (!glow) glow = makeGlow(); initFireflies();
  var mTop = Math.round(clamp(H * 0.08, 20, 60)), avail = H - mTop - 24, ts = Math.round(clamp(avail / 4.4 - 12, 60, 108)), ml = Math.max(4, Math.round(W * 0.008));
  STEP = ts + 12; var mh = Math.min(avail, Math.round(STEP * 4.4) + 14);
  menuEl.style.left = ml + 'px'; menuEl.style.top = mTop + 'px'; menuEl.style.width = (ts + 28) + 'px'; menuEl.style.height = mh + 'px';
  for (var k = 0; k < menuEls.length; k++) menuEls[k].style.width = menuEls[k].style.height = ts + 'px';
  mMin = Math.min(0, mh - (menuEls.length * STEP + 20)); menuSet(clamp(mY, mMin, 0));
  var toolW = ml + ts + 28 + 6, aw = W - toolW - 16; U = clamp(Math.min(W, H) * 0.15, 84, 132);
  var trayH = Math.round(U * 1.55); tray.cx = toolW + 8 + aw / 2; tray.cy = H - 18 - trayH / 2;
  trayBg.style.width = Math.min(aw, U * 5.2) + 'px'; trayBg.style.height = trayH + 'px'; trayBg.style.left = (tray.cx - Math.min(aw, U * 5.2) / 2) + 'px'; trayBg.style.top = (tray.cy - trayH / 2) + 'px';
  var bh = Math.round(U * 1.15); bubbleEl.style.top = '12px'; bubbleEl.style.height = bh + 'px'; bubbleEl.style.fontSize = Math.round(U * 0.7) + 'px';
  var top = bh + 24, availH = tray.cy - trayH / 2 + trayH * 0.22 - top, sh = Math.min(availH, aw * 1.5), sw = sh / 1.5;
  stageRect.w = sw; stageRect.h = sh; stageRect.left = tray.cx - sw / 2; stageRect.top = top + (availH - sh) / 2;
  layoutStage(); placeItems(); layoutBubble();
}
function layoutStage() {
  for (var i = 0; i < AN.length; i++) { var s = AN[i].el.style; s.left = stageRect.left + 'px'; s.top = stageRect.top + 'px'; s.width = stageRect.w + 'px'; s.height = stageRect.h + 'px'; }
}
function frame(ts) {
  var dt = Math.min(0.05, ((ts || 0) - last) / 1000); last = ts || 0; if (dt < 0) dt = 0.016;
  T += dt; drawBg(dt); updateItems(dt); menuInertia(dt); updateParticles(dt); drawFx();
  if (cur) { updateAnimal(cur, dt); drawStage(cur); }
  window.requestAnimationFrame(frame);
}
function imageLoaded() { loadedCount++; if (loadedCount >= ANIMALS.length) hideLoading(); }
function hideLoading() { if (started) return; started = true; var l = $('loading'); l.className = 'gone'; setTimeout(function () { l.style.display = 'none'; }, 700); }
ANIMALS.forEach(function (cfg) { AN.push(buildAnimal(cfg)); });
document.body.className = 'hint';
